@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/* ---------------------------------------------------------------------------
   Tokens. Dark is the default and the primary design; light is its own
   design, not an inversion. Near-black over pure black, paper over pure
   white. See DESIGN.md §6.
--------------------------------------------------------------------------- */

:root {
  color-scheme: light;

  --background: oklch(0.9895 0.0015 265);
  --surface: oklch(0.972 0.0025 265);
  --foreground: oklch(0.205 0.005 265);
  --muted: oklch(0.472 0.006 265);
  --dim: oklch(0.548 0.006 265);
  --border: oklch(0.205 0.005 265 / 0.13);
  --border-strong: oklch(0.205 0.005 265 / 0.26);
  --accent: oklch(0.53 0.155 248);
  --accent-quiet: oklch(0.53 0.155 248 / 0.14);

  /* Heatmap ramp — intensity darkens the paper. */
  --l0: oklch(0.205 0.005 265 / 0.055);
  --l1: oklch(0.62 0.07 248);
  --l2: oklch(0.56 0.11 248);
  --l3: oklch(0.49 0.14 248);
  --l4: oklch(0.41 0.16 250);
}

.dark {
  color-scheme: dark;

  --background: oklch(0.1615 0.004 265);
  --surface: oklch(0.202 0.005 265);
  --foreground: oklch(0.968 0.001 265);
  --muted: oklch(0.712 0.006 265);
  --dim: oklch(0.582 0.007 265);
  --border: oklch(1 0 0 / 0.1);
  --border-strong: oklch(1 0 0 / 0.2);
  --accent: oklch(0.735 0.135 244);
  --accent-quiet: oklch(0.735 0.135 244 / 0.18);

  --l0: oklch(1 0 0 / 0.055);
  --l1: oklch(0.36 0.055 248);
  --l2: oklch(0.5 0.09 246);
  --l3: oklch(0.62 0.12 245);
  --l4: oklch(0.755 0.14 244);
}

@theme inline {
  --color-background: var(--background);
  --color-surface: var(--surface);
  --color-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-dim: var(--dim);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-accent: var(--accent);
  --color-accent-quiet: var(--accent-quiet);

  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace;

  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);
}

/* Six sizes. There is no seventh. */
@theme {
  --text-2xs: 0.6875rem; /* 11 — legend, month labels */
  --text-2xs--line-height: 1.4;
  --text-xs: 0.75rem; /* 12 — labels, metadata, nav */
  --text-xs--line-height: 1.45;
  --text-sm: 0.8125rem; /* 13 — descriptions, code */
  --text-sm--line-height: 1.6;
  --text-base: 0.9375rem; /* 15 — body, prose */
  --text-base--line-height: 1.72;
  --text-lg: 1.0625rem; /* 17 — names, row titles */
  --text-lg--line-height: 1.4;
  --text-2xl: 1.5rem; /* 24 — page + post titles */
  --text-2xl--line-height: 1.25;
}

/* ---------------------------------------------------------------------------
   Base
--------------------------------------------------------------------------- */

@layer base {
  * {
    border-color: var(--border);
  }

  html {
    -webkit-text-size-adjust: 100%;
    font-variant-numeric: tabular-nums;
    scroll-behavior: smooth;
    scroll-padding-top: 6rem;
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: var(--text-base);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    transition:
      background-color 250ms var(--ease-io),
      color 250ms var(--ease-io);
  }

  /* Suppress every transition until after first paint so the stored theme
     never animates in from the wrong colour. */
  .preload *,
  .preload *::before,
  .preload *::after {
    transition: none !important;
    animation: none !important;
  }

  ::selection {
    background: var(--accent-quiet);
    color: var(--foreground);
  }

  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
    border-radius: 2px;
  }

  ::-webkit-scrollbar {
    width: 11px;
    height: 11px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border-strong);
    border: 3px solid var(--background);
    border-radius: 999px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--dim);
  }
}

/* ---------------------------------------------------------------------------
   Chrome
--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  background: var(--surface);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
  translate: -50% 0;
}

.section-label {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--dim);
}

/* Link with a hairline that thickens rather than appearing. Zero layout
   shift, which underline-on-hover cannot promise. */
.link-quiet {
  text-decoration: underline;
  text-decoration-color: var(--border-strong);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition:
    color 150ms var(--ease-out-quint),
    text-decoration-color 150ms var(--ease-out-quint);
}
.link-quiet:hover {
  color: var(--foreground);
  text-decoration-color: var(--accent);
}

/* ---------------------------------------------------------------------------
   Entrance. Rules draw, text settles. Nothing bounces, nothing loops.
--------------------------------------------------------------------------- */

@keyframes rule-draw {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@keyframes settle {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes cell-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.reveal > * {
  animation: settle 380ms var(--ease-out-quint) both;
  animation-delay: calc(var(--i, 0) * 55ms + var(--base-delay, 0ms));
}

.rule {
  height: 1px;
  background: var(--border);
  transform-origin: left;
  animation: rule-draw 420ms var(--ease-out-quint) both;
  animation-delay: var(--base-delay, 0ms);
}

