    { label: "LinkedIn", href: "https://linkedin.com/in/dhruv2mars" },
    { label: "Email", href: "mailto:Dhruv2mars@gmail.com" },
  ] as const satisfies readonly SocialLink[],
  rssPath: "/feed.xml",
} as const;

/** Socials minus mailto, for `sameAs` in structured data. */
export function profileUrls(): string[] {
  return site.socials
    .filter((s) => !s.href.startsWith("mailto:"))
    .map((s) => s.href);
}

  animation-delay: var(--base-delay, 0ms);
}

/* ---------------------------------------------------------------------------
   Masthead avatar slot — a designed absence (DESIGN.md §3). The footprint,
   the border, and the cursor-tracking light are all real; only the portrait
   is missing. Setting site.avatar swaps it in with no layout shift.
--------------------------------------------------------------------------- */

.avatar-slot {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
  background: var(--surface);
}

.avatar-slot::before {
  content: "";
  position: absolute;
  inset: -40%;
  z-index: 1;
  background: radial-gradient(
    42% 42% at var(--lx, 50%) var(--ly, 50%),
    var(--accent-quiet),
    transparent 70%
  );
  opacity: var(--lit, 0);
  transition: opacity 320ms var(--ease-out-quint);
}

/* The grid of dots reads as "an image belongs here", not "an image failed". */
.avatar-slot::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  background-image: radial-gradient(
    currentColor 0.5px,
    transparent 0.5px
  );
  background-size: 4px 4px;
  color: var(--dim);
  opacity: 0.42;
}

/* ---------------------------------------------------------------------------
   Activity grid
--------------------------------------------------------------------------- */

/* One column per week. Columns are the unit of layout, so narrow screens
   simply drop the oldest ones instead of shrinking every cell to a speck. */
.activity-grid {
  --cell-gap: 3px;
  display: grid;
  grid-template-columns: repeat(var(--weeks, 53), minmax(0, 1fr));
  gap: var(--cell-gap);
  width: 100%;
  outline: none;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, minmax(0, 1fr));
  gap: var(--cell-gap);
  padding-top: 1.05rem;
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  line-height: 1;
  color: var(--dim);
  white-space: nowrap;
  pointer-events: none;
}

.activity-cell {
  aspect-ratio: 1;
  border-radius: 2px;
  background: var(--level, var(--l0));
  position: relative;
  animation: cell-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
  transition:
    outline-color 120ms var(--ease-out-quint),
    background-color 150ms var(--ease-out-quint);
  outline: 1px solid transparent;
  outline-offset: 1.5px;
}

.activity-cell[data-active="true"] {
  outline-color: var(--foreground);
}

/* Today is a ring, never a fill — a projection must not read as a record. */
.activity-cell[data-live="true"]::after {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 3px;
  border: 1px solid var(--accent);
}

/* Half a year at a comfortable cell size beats a full year of dust. */
@media (max-width: 40rem) {
  .activity-grid {
    grid-template-columns: repeat(var(--weeks-sm, 27), minmax(0, 1fr));
  }
  .activity-col[data-narrow-hidden="true"] {
    display: none;
  }
}

/* ---------------------------------------------------------------------------
   Rows
--------------------------------------------------------------------------- */

.row-item {
  position: relative;
  display: block;
  padding: 1.125rem 0.75rem;
  margin-inline: -0.75rem;
  border-radius: 6px;
  transition: background-color 160ms var(--ease-out-quint);
}
.row-item:hover {
  background: color-mix(in oklab, var(--surface) 72%, transparent);
}

.row-dest {
  opacity: 0;
  transform: translateY(2px);
  transition:
    opacity 160ms var(--ease-out-quint),
    transform 160ms var(--ease-out-quint);
}
.row-item:hover .row-dest,
.row-item:focus-visible .row-dest {
  opacity: 1;
  transform: none;
}
.row-item:hover .row-year,
.row-item:focus-visible .row-year {
  opacity: 0;
}
.row-year {
  transition: opacity 160ms var(--ease-out-quint);
}

/* ---------------------------------------------------------------------------
   Prose (MDX)
--------------------------------------------------------------------------- */

.prose {
  color: var(--foreground);
  font-size: var(--text-base);
}
.prose > * + * {
  margin-top: 1.35em;
}
.prose h2,
.prose h3 {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 500;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--dim);
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 1rem;
}
.prose a {
  color: var(--foreground);
  text-decoration: underline;
  text-decoration-color: var(--border-strong);
  text-underline-offset: 3px;
  transition: text-decoration-color 150ms var(--ease-out-quint);
}
.prose a:hover {
  text-decoration-color: var(--accent);
}
.prose strong {
  font-weight: 550;
}
.prose ul,
.prose ol {
  padding-left: 1.25rem;
}
.prose ul {
  list-style: disc;
}
.prose ol {
  list-style: decimal;
}
.prose li::marker {
  color: var(--dim);
}
.prose li + li {
  margin-top: 0.5rem;
}
.prose blockquote {
  padding-left: 1.125rem;
  border-left: 1px solid var(--accent);
  color: var(--muted);
}
.prose hr {
  border: 0;
  border-top: 1px solid var(--border);
}
.prose img {
  border-radius: 8px;
  border: 1px solid var(--border);
}
.prose :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.9em;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
.prose pre {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem 1.125rem;
  overflow-x: auto;
}
.prose pre code {
  background: none;
  border: 0;
  padding: 0;
}
.prose .anchor {
  position: absolute;
}

/* sugar-high — four roles, no rainbow */
.prose pre .sh__token--keyword,
.prose pre .sh__token--sign {
  color: var(--accent);
}
.prose pre .sh__token--string,
.prose pre .sh__token--property {
  color: var(--muted);
}
.prose pre .sh__token--comment {
  color: var(--dim);
}
.prose pre .sh__token--identifier,
.prose pre .sh__token--entity {
  color: var(--foreground);
}

/* ---------------------------------------------------------------------------
   Command palette
--------------------------------------------------------------------------- */

@keyframes palette-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.palette-panel {
  animation: palette-in 200ms var(--ease-out-quint) both;
}

.palette-backdrop {
  animation: cell-in 160ms linear both;
  background: color-mix(in oklab, var(--background) 62%, transparent);
  backdrop-filter: blur(6px);
}

/* ---------------------------------------------------------------------------
   Reduced motion: movement goes, colour feedback stays.
--------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
  }
  .reveal > *,
  .rule,
  .activity-cell,
  .palette-panel {
    animation: none !important;
    opacity: 1;
    transform: none;
  }
  .row-dest {
    transition: opacity 120ms linear;
  }
}

