@layer base {
  *,
  ::after,
  ::before,
  ::backdrop,
  ::file-selector-button {
    @apply border-border outline-ring/50;
  }

  ::selection {
    @apply bg-selection text-selection-foreground;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-synthesis-weight: none;
    text-rendering: optimizeLegibility;
  }

  /* Custom scrollbar styling. Thanks @shadcn-ui */
  ::-webkit-scrollbar {
    width: 5px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border);
    border-radius: 5px;
  }
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }

  [id] {
    @apply scroll-mt-18;
  }
}

@layer components {
  [data-rehype-pretty-code-figure] {
    @apply relative my-[1.25em] rounded-xl bg-surface p-1 text-surface-foreground inset-ring-1 inset-ring-border/64;
    @apply has-data-rehype-pretty-code-title:pt-0;
    @apply has-data-[slot=code-block-command]:pt-0;

    pre {
      @apply no-scrollbar overflow-x-auto overscroll-x-contain py-4 outline-none;
    }

    code {
      @apply min-w-full font-mono text-sm;
    }

    [data-line] {
      @apply pr-(--code-padding-right,0) pl-4;
    }
  }

  [data-line] span {
    @apply text-(--shiki-light) dark:text-(--shiki-dark);
  }

  [data-rehype-pretty-code-title] {
    @apply flex items-center gap-3 py-2.5 pr-8.5 pl-3 font-mono text-sm text-muted-foreground [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground;
  }

  [data-line-numbers] {
    counter-reset: line;
  }

  [data-line-numbers] [data-line] {
    @apply pl-0;
  }

  [data-line-numbers] [data-line]::before {
    counter-increment: line;
    content: counter(line);
    @apply sticky left-0 z-1 inline-block w-16 bg-code pe-6 text-right text-sm text-code-number;
  }

  [data-highlighted-line] {
    @apply relative after:pointer-events-none after:absolute after:inset-0 after:z-2 after:bg-code-highlight;
  }

  [data-highlighted-chars] {
    @apply relative bg-transparent before:pointer-events-none before:absolute before:inset-0 before:rounded-sm before:bg-code-highlight;
  }

  [data-fade-overlay] {
    @apply pointer-events-none absolute top-0 right-0 z-1 rounded-tr-lg;

    --fade-linear-gradient: linear-gradient(
      to right,
      transparent 0,
      color-mix(in oklab, var(--fade-color, var(--background)) 20%, transparent)
        10px,
      color-mix(in oklab, var(--fade-color, var(--background)) 50%, transparent)
        25px,
      color-mix(in oklab, var(--fade-color, var(--background)) 80%, transparent)
        35px,
      var(--fade-color, var(--background)) 45px
    );

    --fade-radial-gradient: radial-gradient(
      ellipse at top right,
      var(--fade-color, var(--background)) 30%,
