   287	/* ---------------------------------------------------------------------------
   288	   Activity grid
   289	--------------------------------------------------------------------------- */
   290	
   291	/* One column per week. Columns are the unit of layout, so narrow screens
   292	   simply drop the oldest ones instead of shrinking every cell to a speck. */
   293	.activity-grid {
   294	  --cell-gap: 3px;
   295	  display: grid;
   296	  grid-template-columns: repeat(var(--weeks, 53), minmax(0, 1fr));
   297	  gap: var(--cell-gap);
   298	  width: 100%;
   299	  outline: none;
   300	}
   301	
   302	.activity-col {
   303	  position: relative;
   304	  display: grid;
   305	  grid-template-rows: repeat(7, minmax(0, 1fr));
   306	  gap: var(--cell-gap);
   307	  padding-top: 1.05rem;
   308	}
   309	
   310	/* Sits above its own column, allowed to overflow it. */
   311	.activity-month {
   312	  position: absolute;
   313	  top: 0;
   314	  left: 0;
   315	  font-family: var(--font-mono);
   316	  font-size: var(--text-2xs);
   317	  line-height: 1;
   318	  color: var(--dim);
   319	  white-space: nowrap;
   320	  pointer-events: none;
   321	}
   322	
   323	.activity-cell {
   324	  aspect-ratio: 1;
   325	  border-radius: 2px;
   326	  background: var(--level, var(--l0));
   327	  position: relative;
   328	  animation: cell-in 260ms var(--ease-out-quint) both;
   329	  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
   330	  transition:
   331	    outline-color 120ms var(--ease-out-quint),
   332	    background-color 150ms var(--ease-out-quint);
   333	  outline: 1px solid transparent;
   334	  outline-offset: 1.5px;
   335	}
   336	
   337	.activity-cell[data-active="true"] {
   338	  outline-color: var(--foreground);
   339	}
   340	
   341	/* Today is a ring, never a fill — a projection must not read as a record. */
   342	.activity-cell[data-live="true"]::after {
   343	  content: "";
   344	  position: absolute;
   345	  inset: -2px;
   346	  border-radius: 3px;
   347	  border: 1px solid var(--accent);
